package cli

func addUserCooperationHelp(registry map[string]helpTopic) {
	flags := []helpFlag{{"--profile <profile>", "配置名称，复用已确认环境"}, {"--as user", "仅支持 user，省略时也固定 user"}, {"--cooperation-id <id>", "必填，正 int64 协商 ID，不是合同 ID"}, {"--output <json|yaml|table>", "响应输出格式"}, {"--raw", "输出原始响应"}}
	registry["contract cooperation get"] = helpTopic{Name: "contract cooperation get", Summary: "以 user 身份查询协商基本信息、当前轮次文件、协商人及背景。", Usage: []string{"contract-cli contract cooperation get --cooperation-id <id> [flags]"}, Flags: flags, Examples: []string{"contract-cli contract cooperation get --cooperation-id 123 --profile contract --as user --output json"}, Notes: []string{"GET /open-apis/contract/v1/mcp/cooperations/{cooperation_id}；固定 user_id/open_department_id。", "与 review cooperation get 共用详情请求；旧审查命令保留。"}}
	registry["contract cooperation history-files"] = helpTopic{Name: "contract cooperation history-files", Usage: []string{"contract-cli contract cooperation history-files list [flags]"}, Commands: []helpCommand{{"contract-cli contract cooperation history-files list --cooperation-id <id> [flags]", "user 身份查询版本文件和确认留痕文件"}}}
	historyFlags := append(append([]helpFlag(nil), flags...), helpFlag{"--include-current-version[=true|false]", "是否包含当前未完成协商轮次的版本，默认 true；排除时传 =false"})
	registry["contract cooperation history-files list"] = helpTopic{Name: "contract cooperation history-files list", Summary: "以 user 身份查询协商历史版本、版本文件及确认留痕文件。", Usage: []string{"contract-cli contract cooperation history-files list --cooperation-id <id> [flags]"}, Flags: historyFlags, Examples: []string{"contract-cli contract cooperation history-files list --cooperation-id 123 --include-current-version=false --profile contract --as user --output json"}, Notes: []string{"GET /open-apis/contract/v1/mcp/cooperations/{cooperation_id}/history_files。", "false 仅在未发起（0）或协商中（2）时排除当前轮次；协商完成（3）或已结束（6）仍可返回最终版。", "latest_version 表示各文件组返回版本中的最高版本；history 包含代表项自身。", "只查询文件信息，不下载文件、不发起审查；固定 user_id/open_department_id。"}}
}
